mat2 rot_mat = mat2(cos(vec4(0,11,33,0)+0.03));
mat2 rot_mat2 = mat2(cos(vec4(0,11,33,0)+135.3));
// map the world
float map(vec3 point) {
   vec3 v = point;
   vec3 dist = v - 222.;
   for(float i=100.; i>.4; i*=.4) {
       v.xz *= rot_mat;
       v.xy *= rot_mat2;
       dist = max(dist, min(min( v = i*.9 - abs( mod(v,i+i)-i), v.x ), v.z));
   }
   return dist.y;
}

// Scene distance field
float mapScene(vec3 p) {
    return map(p);
}

// Shadow calculation
float shadow(vec3 ro, vec3 rd) {
    float t = 0.01;
    float res = 1.0;
    for (int i = 0; i < 18; i++) {
        float d = mapScene(ro + rd * t);
        if (d < 0.01) return 0.0;
        res = min(res, 10.0 * d / t);
        t += d;
        if (t > 10.0) break;
    }
    return res;
}

// Calculate normal
vec3 calcNormal(vec3 p) {
    float d = mapScene(p);
    vec2 e = vec2(0.001, 0.0);
    vec3 n = d - vec3(
        mapScene(p - e.xyy),
        mapScene(p - e.yxy),
        mapScene(p - e.yyx)
    );
    return normalize(n);
}


// Ambient occlusion calculation
float ambientOcclusion(vec3 p, vec3 normal) {
    float ao = 0.0;
    float scale = 1.0;
    for (int i = 1; i <= 5; i++) {
        float t = 0.01 * float(i);
        ao += scale * max(0.0, t - mapScene(p + normal * t));
        scale *= 0.5;
    }
    return clamp(1.0 - ao, 0.0, 1.0);
}
  // Light position
    vec3 lightPos = vec3(2.0, 3.0, 3.0);

// Random function for GI
float rand(vec3 co) {
    return fract(sin(dot(co, vec3(12.9898, 78.233, 45.164))) * 43758.5453);
}


// Global illumination approximation
vec3 globalIllumination(vec3 p, vec3 normal) {
    vec3 hemiColor = vec3(0.1, 0.2, 0.3); // Approximation of indirect light
    vec3 lightDir = normalize(lightPos - p);
    float bounceStrength = 0.9;
    vec3 bounceLight = vec3(0.0);

    for (int i = 0; i < 4; i++) {
        p++;
        p += float(i);
        vec3 randomDir = normalize(reflect(normalize(vec3(rand(p), rand(p.zxy), rand(p.yzx))), normal));
        float weight = max(dot(normal, randomDir), 0.0);
        bounceLight += weight * hemiColor * bounceStrength;
    }

    return bounceLight / 4.0;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Map screen space to normalized coordinates
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Camera setup
    vec3 ro = vec3(0.0, 0.0+sin(iTime*.5)*3., 5.0); // Camera position
    vec3 rd = normalize(vec3(uv, -1.0)); // Ray direction 

    // Raymarching loop
    vec3 color = vec3(0.0);
    float t = 0.0;
    for (int i = 0; i < 50; i++) {
        vec3 p = ro + rd * t;
        float d = mapScene(p);
        if (d < 0.001) {
            // Lighting
            vec3 normal = calcNormal(p);
            vec3 lightDir = normalize(lightPos - p);
            float diff = max(dot(normal, lightDir), 0.0) * 2.5;

            float sh = shadow(p + normal * 0.01, lightDir);
            float ao = ambientOcclusion(p, normal);

            vec3 directLight = vec3(0.2, 0.5, 0.8) * diff * sh;
            vec3 gi = globalIllumination(p, normal);

             // Use the texture function

            color = (directLight + gi) * ao; // Combine lighting components with texture


            break;
        }
        t += d;
        if (t > 220.0) break;
    }

    fragColor = vec4(color, 1.0);
}
